import{_ as t,o,c as a,a2 as s}from"./chunks/framework.R5qXEdDn.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md","lastUpdated":1794906572000}'),r={name:"reference/troubleshooting.md"};function i(n,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Find the message you see, then its cause and fix.</p><div class="tip custom-block"><p class="custom-block-title">Start with the doctor</p><p>Run <code>./gradlew svelteDoctor</code> first: it checks the frontend setup and lists most problems on this page at once. Add <code>--fix</code> and it repairs the ones that need no decision from you: a missing <code>#api</code> import, a <code>tsconfig.json</code> that does not extend <code>$app/tsconfig</code>, <code>$lib</code> imports left over from SvelteKit 2, and a <code>node_modules</code> folder whose packages lost their files, which it deletes so the next build installs it again. It prints each change as <code>FIXED</code>, and everything else stays a finding for you. See <a href="./../guide/checks-and-tooling#sveltedoctor">svelteDoctor</a>.</p></div><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You see</th><th>Go to</th></tr></thead><tbody><tr><td>The build fails before the frontend is built</td><td><a href="#build">Build</a></td></tr><tr><td>The app does not start</td><td><a href="#startup">Startup</a></td></tr><tr><td>A request answers 403, 413, 429 or 503</td><td><a href="#requests">Requests</a></td></tr><tr><td>Something is off while <code>svelteDevAll</code> runs</td><td><a href="#development">Development</a></td></tr><tr><td>A check, hook or browser test fails</td><td><a href="#checks-and-tests">Checks and tests</a></td></tr></tbody></table><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><h3 id="ktor-svelte-found-no-lockfile" tabindex="-1">ktor-svelte found no lockfile <a class="header-anchor" href="#ktor-svelte-found-no-lockfile" aria-label="Permalink to &quot;ktor-svelte found no lockfile&quot;">​</a></h3><ul><li><strong>Cause:</strong> the frontend has no <code>bun.lock</code>, <code>pnpm-lock.yaml</code>, <code>package-lock.json</code> or <code>yarn.lock</code>, so the plugin cannot tell which package manager to use.</li><li><strong>Fix:</strong> install the dependencies once with your package manager, or set <code>svelte { packageManager = PackageManager.Bun }</code>.</li></ul><h3 id="ktor-svelte-could-not-find-bun-on-path" tabindex="-1">ktor-svelte could not find bun on PATH <a class="header-anchor" href="#ktor-svelte-could-not-find-bun-on-path" aria-label="Permalink to &quot;ktor-svelte could not find bun on PATH&quot;">​</a></h3><ul><li><strong>Cause:</strong> the package manager the lockfile asks for is not installed, or Gradle cannot see it.</li><li><strong>Fix:</strong> install it and restart the Gradle daemon with <code>./gradlew --stop</code> so it picks up the new <code>PATH</code>, or set <code>packageManager</code> to one you have.</li><li><strong>Or:</strong> let the plugin download Bun for you with <code>svelte { bunVersion = &quot;1.3.14&quot; }</code>. See <a href="./gradle#pin-bun">Pin Bun</a>.</li></ul><h3 id="ktor-svelte-found-no-html-files" tabindex="-1">ktor-svelte found no HTML files <a class="header-anchor" href="#ktor-svelte-found-no-html-files" aria-label="Permalink to &quot;ktor-svelte found no HTML files&quot;">​</a></h3><ul><li><strong>Cause:</strong> the frontend build produced no pages where the plugin looked.</li><li><strong>Fix:</strong> check that the frontend uses <code>adapter-static</code>, and that <code>svelte { outputDir }</code> matches the adapter&#39;s <code>pages</code> option. The default for both is <code>build</code>.</li></ul><h3 id="svelte-outputdir-must-be-a-path-inside-svelte-frontenddir" tabindex="-1">svelte.outputDir must be a path inside svelte.frontendDir <a class="header-anchor" href="#svelte-outputdir-must-be-a-path-inside-svelte-frontenddir" aria-label="Permalink to &quot;svelte.outputDir must be a path inside svelte.frontendDir&quot;">​</a></h3><ul><li><strong>Cause:</strong> <code>outputDir</code> points outside the frontend folder.</li><li><strong>Fix:</strong> give it relative to <code>frontendDir</code>, such as <code>outputDir = &quot;build&quot;</code>.</li></ul><h3 id="ktor-svelte-has-no-setting-x-in-svelte" tabindex="-1">ktor-svelte has no setting &#39;x&#39; in svelte <a class="header-anchor" href="#ktor-svelte-has-no-setting-x-in-svelte" aria-label="Permalink to &quot;ktor-svelte has no setting &#39;x&#39; in svelte { }&quot;">​</a></h3><ul><li><strong>Cause:</strong> a Groovy build script assigns a setting that does not exist, usually a typo.</li><li><strong>Fix:</strong> the message names the closest setting and lists all of them. See <a href="./gradle">Gradle settings</a> for what each one does.</li></ul><h3 id="frontend-libraries-are-out-of-sync" tabindex="-1">Frontend libraries are out of sync <a class="header-anchor" href="#frontend-libraries-are-out-of-sync" aria-label="Permalink to &quot;Frontend libraries are out of sync&quot;">​</a></h3><ul><li><strong>Cause:</strong> <code>build.gradle.kts</code> changed the frontend libraries, but <code>package.json</code>, the lockfile or the generated files were not updated.</li><li><strong>Fix:</strong> run <code>./gradlew svelteSync</code> and commit the result.</li></ul><h3 id="ktor-svelte-generates-vite-config-ts-but-found-your-own-version" tabindex="-1">ktor-svelte generates vite.config.ts, but found your own version <a class="header-anchor" href="#ktor-svelte-generates-vite-config-ts-but-found-your-own-version" aria-label="Permalink to &quot;ktor-svelte generates vite.config.ts, but found your own version&quot;">​</a></h3><ul><li><strong>Cause:</strong> the plugin needs to own <code>vite.config.ts</code> and the hooks files once frontend libraries are on.</li><li><strong>Fix:</strong> move your own Vite settings to <code>vite.user.ts</code>, merge custom hooks by hand, delete those files and run <code>svelteSync</code>.</li></ul><h3 id="generated-typescript-is-out-of-date" tabindex="-1">Generated TypeScript is out of date <a class="header-anchor" href="#generated-typescript-is-out-of-date" aria-label="Permalink to &quot;Generated TypeScript is out of date&quot;">​</a></h3><ul><li><strong>Cause:</strong> <code>check</code> runs <code>svelteVerifyTs</code>, which found that a route or DTO changed but the committed client did not.</li><li><strong>Fix:</strong> run <code>./gradlew svelteGenerateTs</code>, or start the app in development mode, and commit the files in <code>frontend/src/lib/api</code>.</li></ul><h3 id="ktor-svelte-found-secret-values-in-the-frontend-build" tabindex="-1">ktor-svelte found secret values in the frontend build <a class="header-anchor" href="#ktor-svelte-found-secret-values-in-the-frontend-build" aria-label="Permalink to &quot;ktor-svelte found secret values in the frontend build&quot;">​</a></h3><ul><li><strong>Cause:</strong> <code>svelteVerifyLeaks</code> found the value of a secret environment variable or a <code>.env</code> entry in the built files.</li><li><strong>Fix:</strong> read that value on the server only. A value that is meant to be public belongs in <code>svelte { buildEnv }</code>, or gets a name that starts with <code>PUBLIC_</code>. See <a href="./../features/runtime-config#secrets-in-the-frontend-build">Secrets in the frontend build</a>.</li></ul><h3 id="undefined-is-not-an-object-evaluating-ts-sys-readfile" tabindex="-1">undefined is not an object (evaluating &#39;ts.sys.readFile&#39;) <a class="header-anchor" href="#undefined-is-not-an-object-evaluating-ts-sys-readfile" aria-label="Permalink to &quot;undefined is not an object (evaluating &#39;ts.sys.readFile&#39;)&quot;">​</a></h3><ul><li><strong>Cause:</strong> the frontend uses TypeScript 7, which SvelteKit 3 cannot load yet. It usually arrives through an automatic dependency update.</li><li><strong>Fix:</strong> set <code>&quot;typescript&quot;: &quot;^6.0.0&quot;</code> in <code>frontend/package.json</code> and install again.</li><li><strong>Keep it away:</strong> tell your update bot to ignore major versions of <code>typescript</code>.</li></ul><h3 id="cannot-find-module-rolldown-parseast-or-another-package-that-is-installed" tabindex="-1">Cannot find module &#39;rolldown/parseAst&#39;, or another package that is installed <a class="header-anchor" href="#cannot-find-module-rolldown-parseast-or-another-package-that-is-installed" aria-label="Permalink to &quot;Cannot find module &#39;rolldown/parseAst&#39;, or another package that is installed&quot;">​</a></h3><ul><li><strong>Cause:</strong> the install was cut short: the package&#39;s folder exists in <code>node_modules</code>, but its files do not, and the package manager still reported success. <code>./gradlew svelteDoctor</code> names the packages that lost their files.</li><li><strong>Fix:</strong> run <code>./gradlew svelteClean</code> and install again.</li><li><strong>If they come back empty:</strong> the package manager&#39;s cache is the cause, so clear it with the command <code>svelteDoctor</code> prints, such as <code>bun pm cache rm</code>, and install once more.</li></ul><h3 id="the-frontend-build-failed-with-exit-code-1" tabindex="-1">The frontend build failed with exit code 1 <a class="header-anchor" href="#the-frontend-build-failed-with-exit-code-1" aria-label="Permalink to &quot;The frontend build failed with exit code 1&quot;">​</a></h3><ul><li><strong>Cause:</strong> ktor-svelte hides the package manager and Vite output while it succeeds and prints all of it when it fails, above this message. The real error is there.</li><li><strong>Fix:</strong> to see the output every time, add <code>-Psvelte.verbose=true</code>.</li></ul><h2 id="startup" tabindex="-1">Startup <a class="header-anchor" href="#startup" aria-label="Permalink to &quot;Startup&quot;">​</a></h2><h3 id="ktor-svelte-found-no-frontend-build" tabindex="-1">ktor-svelte found no frontend build <a class="header-anchor" href="#ktor-svelte-found-no-frontend-build" aria-label="Permalink to &quot;ktor-svelte found no frontend build&quot;">​</a></h3><ul><li><strong>Cause:</strong> the app runs in production mode, but the JAR has no frontend in it.</li><li><strong>Fix:</strong> build it with the Gradle plugin and without <code>-Psvelte.skip=true</code> or <code>-Psvelte.dev=true</code>.</li><li><strong>During development:</strong> start it with <code>-Dio.ktor.development=true</code>, or use <code>svelteDevAll</code>, which does that for you.</li></ul><h3 id="ktor-svelte-manifest-has-format-version-2-but-this-runtime-reads-version-1" tabindex="-1">ktor-svelte manifest has format version 2, but this runtime reads version 1 <a class="header-anchor" href="#ktor-svelte-manifest-has-format-version-2-but-this-runtime-reads-version-1" aria-label="Permalink to &quot;ktor-svelte manifest has format version 2, but this runtime reads version 1&quot;">​</a></h3><ul><li><strong>Cause:</strong> the Gradle plugin and <code>ktor-svelte-server</code> have different versions.</li><li><strong>Fix:</strong> use the same version for both. With <code>addRuntimeDependency</code> on, which is the default, the plugin adds the matching runtime for you.</li></ul><h3 id="contentnegotiation-is-already-installed" tabindex="-1">ContentNegotiation is already installed <a class="header-anchor" href="#contentnegotiation-is-already-installed" aria-label="Permalink to &quot;ContentNegotiation is already installed&quot;">​</a></h3><ul><li><strong>Cause:</strong> you install <code>ContentNegotiation</code> yourself and also list formats in <code>transport { }</code>.</li><li><strong>Fix:</strong> keep one of the two. The same applies to <code>Compression</code> and <code>compression()</code>.</li></ul><h3 id="requestbodylimit-is-already-installed-or-ratelimit-is-already-installed" tabindex="-1">RequestBodyLimit is already installed, or RateLimit is already installed <a class="header-anchor" href="#requestbodylimit-is-already-installed-or-ratelimit-is-already-installed" aria-label="Permalink to &quot;RequestBodyLimit is already installed, or RateLimit is already installed&quot;">​</a></h3><ul><li><strong>Cause:</strong> ktor-svelte installs these plugins for its body and rate limits.</li><li><strong>Fix:</strong> to use your own, set <code>maxApiBodySize = null</code> or <code>rateLimit { enabled = false }</code>.</li></ul><h3 id="ktor-svelte-will-not-proxy-to-this-url-because-it-is-not-on-this-machine" tabindex="-1">ktor-svelte will not proxy to this URL because it is not on this machine <a class="header-anchor" href="#ktor-svelte-will-not-proxy-to-this-url-because-it-is-not-on-this-machine" aria-label="Permalink to &quot;ktor-svelte will not proxy to this URL because it is not on this machine&quot;">​</a></h3><ul><li><strong>Cause:</strong> <code>dev { url }</code> or <code>KTOR_SVELTE_DEV_SERVER</code> points at another host.</li><li><strong>Fix:</strong> use a loopback address, or set <code>dev { allowRemote = true }</code> if you trust that machine.</li></ul><h3 id="install-the-svelte-plugin-before-calling-svelte-in-routing" tabindex="-1">Install the Svelte plugin before calling svelte() in routing <a class="header-anchor" href="#install-the-svelte-plugin-before-calling-svelte-in-routing" aria-label="Permalink to &quot;Install the Svelte plugin before calling svelte() in routing&quot;">​</a></h3><ul><li><strong>Cause:</strong> with <code>routing = SvelteRouting.Manual</code>, <code>svelte()</code> ran before the plugin was installed.</li><li><strong>Fix:</strong> call <code>install(Svelte)</code> before the <code>routing { }</code> block that calls <code>svelte()</code>.</li></ul><h3 id="errorcodes-currentuser-permissions-or-preferences-is-already-set" tabindex="-1">errorCodes, currentUser, permissions or preferences is already set <a class="header-anchor" href="#errorcodes-currentuser-permissions-or-preferences-is-already-set" aria-label="Permalink to &quot;errorCodes, currentUser, permissions or preferences is already set&quot;">​</a></h3><ul><li><strong>Cause:</strong> an app has one enum of error codes, one kind of signed-in user, one enum of permissions and one class of preferences, and one of them was declared twice.</li><li><strong>Fix:</strong> keep one declaration in <code>install(Svelte)</code>.</li></ul><h3 id="the-ktor-route-get-about-hides-the-frontend-page-about-html" tabindex="-1">The Ktor route GET /about hides the frontend page about.html <a class="header-anchor" href="#the-ktor-route-get-about-hides-the-frontend-page-about-html" aria-label="Permalink to &quot;The Ktor route GET /about hides the frontend page about.html&quot;">​</a></h3><ul><li><strong>Cause:</strong> a route in your app answers the same path as a prerendered page, so the page is never served.</li><li><strong>Fix:</strong> move the route under your API prefix, or rename the page.</li></ul><h2 id="requests" tabindex="-1">Requests <a class="header-anchor" href="#requests" aria-label="Permalink to &quot;Requests&quot;">​</a></h2><h3 id="_403-cross-origin-api-request-refused" tabindex="-1">403: Cross-origin API request refused <a class="header-anchor" href="#_403-cross-origin-api-request-refused" aria-label="Permalink to &quot;403: Cross-origin API request refused&quot;">​</a></h3><ul><li><strong>Cause:</strong> the origin check refused a write from another site.</li><li><strong>Fix:</strong> if that site is yours, such as a separate admin frontend, add it with <code>allowedOrigins(&quot;https://admin.example.com&quot;)</code>.</li><li><strong>Behind a proxy that changes the host:</strong> install <code>XForwardedHeaders</code> so the app sees the host the browser used. See <a href="./../security#api-request-guards">Security</a>.</li></ul><h3 id="_413-request-body-is-larger-than-the-limit" tabindex="-1">413: Request body is larger than the limit <a class="header-anchor" href="#_413-request-body-is-larger-than-the-limit" aria-label="Permalink to &quot;413: Request body is larger than the limit&quot;">​</a></h3><ul><li><strong>Cause:</strong> API bodies are limited to 1 MiB.</li><li><strong>Fix:</strong> raise <code>maxApiBodySize</code> for apps that accept uploads.</li></ul><h3 id="_400-request-json-is-nested-deeper-than-64-levels" tabindex="-1">400: Request JSON is nested deeper than 64 levels <a class="header-anchor" href="#_400-request-json-is-nested-deeper-than-64-levels" aria-label="Permalink to &quot;400: Request JSON is nested deeper than 64 levels&quot;">​</a></h3><ul><li><strong>Cause:</strong> the JSON body nests deeper than <code>maxJsonDepth</code>, or has a string longer than <code>maxJsonStringLength</code>.</li><li><strong>Fix:</strong> raise the limit if your API really takes such bodies, or set it to <code>null</code>. See <a href="./../security#api-request-guards">Security</a>.</li></ul><h3 id="_429-too-many-requests" tabindex="-1">429: Too Many Requests <a class="header-anchor" href="#_429-too-many-requests" aria-label="Permalink to &quot;429: Too Many Requests&quot;">​</a></h3><ul><li><strong>Cause:</strong> a client sent more than 120 writes to API paths in a minute, or hit a named limit.</li><li><strong>Behind a proxy:</strong> install <code>XForwardedHeaders</code>, or all users share one limit.</li><li><strong>Fix:</strong> raise <code>rateLimit { apiWrites = ... }</code> if your app writes a lot.</li></ul><h3 id="_503-in-development-no-vite-and-no-build" tabindex="-1">503 in development: no Vite and no build <a class="header-anchor" href="#_503-in-development-no-vite-and-no-build" aria-label="Permalink to &quot;503 in development: no Vite and no build&quot;">​</a></h3><ul><li><strong>Cause:</strong> the app runs in development mode, Vite is not running and there is no frontend build.</li><li><strong>Fix:</strong> start everything with <code>./gradlew svelteDevAll</code>, or Vite alone with <code>./gradlew svelteDev</code>.</li></ul><h3 id="_403-the-dev-proxy-only-answers-requests-from-this-machine" tabindex="-1">403: The dev proxy only answers requests from this machine <a class="header-anchor" href="#_403-the-dev-proxy-only-answers-requests-from-this-machine" aria-label="Permalink to &quot;403: The dev proxy only answers requests from this machine&quot;">​</a></h3><ul><li><strong>Cause:</strong> you opened the app from another device while it runs in development mode.</li><li><strong>Fix:</strong> set <code>dev { allowRemote = true }</code> on a network you trust.</li></ul><h3 id="a-page-shows-a-blank-screen-after-a-deploy" tabindex="-1">A page shows a blank screen after a deploy <a class="header-anchor" href="#a-page-shows-a-blank-screen-after-a-deploy" aria-label="Permalink to &quot;A page shows a blank screen after a deploy&quot;">​</a></h3><ul><li><strong>Cause:</strong> the browser has an old page that loads chunks which no longer exist. ktor-svelte answers those with 404 on purpose, so SvelteKit reloads the page.</li><li><strong>Fix:</strong> if it does not reload, check that nothing in front of the app caches HTML: pages are sent with <code>Cache-Control: no-cache</code>.</li></ul><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><h3 id="the-browser-logs-a-websocket-error-for-hmr" tabindex="-1">The browser logs a WebSocket error for HMR <a class="header-anchor" href="#the-browser-logs-a-websocket-error-for-hmr" aria-label="Permalink to &quot;The browser logs a WebSocket error for HMR&quot;">​</a></h3><ul><li><strong>Cause:</strong> without <code>server.hmr.clientPort</code> in <code>vite.config.ts</code>, Vite&#39;s client first tries Ktor&#39;s port. Hot reload still works after one error.</li><li><strong>Fix:</strong> set <code>server: { hmr: { clientPort: 5173, protocol: &#39;ws&#39; } }</code>. Projects from <code>svelteInit</code> already set it.</li></ul><h3 id="a-port-is-already-in-use" tabindex="-1">A port is already in use <a class="header-anchor" href="#a-port-is-already-in-use" aria-label="Permalink to &quot;A port is already in use&quot;">​</a></h3><ul><li><strong>Cause:</strong> a Vite or app process from an earlier run is still alive, usually because a terminal was killed.</li><li><strong>Fix:</strong> <code>svelteDevAll</code> stops what an earlier <code>svelteDevAll</code> left running by itself. For anything else, run <code>./gradlew --stop</code>, or stop the process on that port. See <a href="./../guide/dev-workflow#when-a-port-is-still-in-use">When a port is still in use</a>.</li></ul><h3 id="port-5173-which-vite-needs-is-in-use-by-another-program" tabindex="-1">Port 5173, which Vite needs, is in use by another program <a class="header-anchor" href="#port-5173-which-vite-needs-is-in-use-by-another-program" aria-label="Permalink to &quot;Port 5173, which Vite needs, is in use by another program&quot;">​</a></h3><ul><li><strong>Cause:</strong> a program <code>svelteDevAll</code> did not start holds Vite&#39;s port or the debug port, so the task stops before starting anything.</li><li><strong>Fix:</strong> stop that program, or use another port with <code>svelte { dev { port = 5174 } }</code> or <code>dev { debugPort = ... }</code>.</li></ul><h3 id="types-do-not-update-after-a-kotlin-change" tabindex="-1">Types do not update after a Kotlin change <a class="header-anchor" href="#types-do-not-update-after-a-kotlin-change" aria-label="Permalink to &quot;Types do not update after a Kotlin change&quot;">​</a></h3><ul><li><strong>Cause:</strong> the client is generated when the app starts in development mode with <code>generateTs = true</code>.</li><li><strong>Fix:</strong> with <code>svelteDevAll</code>, that happens after every Kotlin change. With separate terminals, restart the app, or run <code>./gradlew svelteGenerateTs</code>.</li></ul><h3 id="the-browser-does-not-trust-the-https-certificate-in-development" tabindex="-1">The browser does not trust the HTTPS certificate in development <a class="header-anchor" href="#the-browser-does-not-trust-the-https-certificate-in-development" aria-label="Permalink to &quot;The browser does not trust the HTTPS certificate in development&quot;">​</a></h3><ul><li><strong>Cause:</strong> the development certificate authority in <code>~/.ktor-svelte/dev-https</code> is not in your trust store yet.</li><li><strong>Fix:</strong> run the command the first <code>svelteDevAll</code> printed, such as <code>certutil -addstore -user Root</code> on Windows. In Firefox, import <code>ca.crt</code> under Settings, Certificates, Authorities. See <a href="./../guide/dev-workflow#https-in-development">HTTPS in development</a>.</li></ul><h3 id="the-console-warns-with-window-fetch-in-load" tabindex="-1">The console warns with window_fetch_in_load <a class="header-anchor" href="#the-console-warns-with-window-fetch-in-load" aria-label="Permalink to &quot;The console warns with window_fetch_in_load&quot;">​</a></h3><ul><li><strong>Cause:</strong> an API call in a <code>load</code> function does not use SvelteKit&#39;s <code>fetch</code>.</li><li><strong>Fix:</strong> use <code>apiWith(event)</code>, or pass <code>{ fetch }</code> as the last argument. <code>./gradlew svelteVerifyLoads</code> finds every such call. See <a href="./../features/calling-the-api#in-load-functions">In load functions</a>.</li></ul><h3 id="the-page-signs-me-out-after-every-kotlin-change" tabindex="-1">The page signs me out after every Kotlin change <a class="header-anchor" href="#the-page-signs-me-out-after-every-kotlin-change" aria-label="Permalink to &quot;The page signs me out after every Kotlin change&quot;">​</a></h3><ul><li><strong>Cause:</strong> your sessions do not survive a restart, such as with a signing key that is generated at startup.</li><li><strong>Fix:</strong> read the key from the environment, so it stays the same across restarts. To stop pages from reloading their data after a restart, set <code>dev { refreshAfterRestart = false }</code>.</li></ul><h2 id="checks-and-tests" tabindex="-1">Checks and tests <a class="header-anchor" href="#checks-and-tests" aria-label="Permalink to &quot;Checks and tests&quot;">​</a></h2><h3 id="sveltedoctor-found-problems-to-fix" tabindex="-1">svelteDoctor found problems to fix <a class="header-anchor" href="#sveltedoctor-found-problems-to-fix" aria-label="Permalink to &quot;svelteDoctor found problems to fix&quot;">​</a></h3><ul><li><strong>Cause:</strong> at least one finding is an <code>ERROR</code>.</li><li><strong>Fix:</strong> each line says what to do. <code>./gradlew svelteDoctor --fix</code> repairs the ones that need no decision.</li></ul><h3 id="the-pre-commit-hook-already-exists-and-was-not-written-by-ktor-svelte" tabindex="-1">The pre-commit hook already exists and was not written by ktor-svelte <a class="header-anchor" href="#the-pre-commit-hook-already-exists-and-was-not-written-by-ktor-svelte" aria-label="Permalink to &quot;The pre-commit hook already exists and was not written by ktor-svelte&quot;">​</a></h3><ul><li><strong>Cause:</strong> another tool installed a pre-commit hook, and <code>svelteGitHooks</code> never replaces it.</li><li><strong>Fix:</strong> call <code>./gradlew formatCheck svelteVerifySync</code> from that hook yourself, or delete it and run <code>svelteGitHooks</code> again.</li></ul><h3 id="not-inside-a-git-repository-so-there-is-nowhere-to-install-a-hook" tabindex="-1">Not inside a git repository, so there is nowhere to install a hook <a class="header-anchor" href="#not-inside-a-git-repository-so-there-is-nowhere-to-install-a-hook" aria-label="Permalink to &quot;Not inside a git repository, so there is nowhere to install a hook&quot;">​</a></h3><ul><li><strong>Cause:</strong> <code>svelteGitHooks</code> ran in a folder that is not a git clone.</li><li><strong>Fix:</strong> run <code>git init</code> first, or run the task in the clone.</li></ul><h3 id="the-app-did-not-answer-within-60-seconds" tabindex="-1">The app did not answer within 60 seconds <a class="header-anchor" href="#the-app-did-not-answer-within-60-seconds" aria-label="Permalink to &quot;The app did not answer within 60 seconds&quot;">​</a></h3><ul><li><strong>Cause:</strong> a browser test, <code>svelteSmokeTest</code> or <code>svelteVerifyA11y</code> started the packaged app, and it did not answer in time or stopped. Usually a variable or a database it needs is missing.</li><li><strong>Fix:</strong> read the app&#39;s output: <code>build/ktor-svelte/smoke-test.log</code> for the smoke test, the file in <code>app.log</code> in a browser test. Give the app what it needs, or more time with <code>--start-seconds</code> for the smoke test.</li></ul><h3 id="the-app-ignores-the-port-in-tests" tabindex="-1">The app ignores the port in tests <a class="header-anchor" href="#the-app-ignores-the-port-in-tests" aria-label="Permalink to &quot;The app ignores the port in tests&quot;">​</a></h3><ul><li><strong>Cause:</strong> the port is passed as the <code>PORT</code> variable and as <code>-port</code>, and the app reads neither.</li><li><strong>Fix:</strong> read one of them, as <code>EngineMain</code> does with <code>-port</code>.</li></ul><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p>Open an <a href="https://github.com/nijasc/ktor-svelte/issues" target="_blank" rel="noreferrer">issue</a> with the full message, your <code>install(Svelte)</code> and <code>svelte { }</code> blocks, and the output of <code>./gradlew svelteDoctor</code>.</p>',90)])])}const p=t(r,[["render",i]]);export{g as __pageData,p as default};
